/**
 * admin-proposals' view (SPEC §6): the changes the agent proposes to itself, as pull requests from
 * `pikit/self/*`, open first with their checks, then the last merged or rejected; and a page per
 * proposal (`proposal.tsx`) to read it and approve or reject it. It reads the component's own routes,
 * `/admin/api/admin-proposals/*`, slowly: each read asks GitHub.
 *
 * Until self-improvement is connected (no repository, or no read token: `503 not_connected`), the page
 * says what is missing and how to connect it, which the Settings dialog's Self-improvement does.
 */

import { Activity, Clock, GitBranch, GitPullRequest, User } from "iconoir-react";
import { useState } from "react";
import { ValuePill } from "@/components/bui/Chip";
import EmptyState from "@/components/bui/EmptyState";
import { FilterChips } from "@/components/bui/FilterTable";
import { Page, PageLoading, Section } from "@/components/bui/Page";
import RecordsTable, { type RecordColumn, RecordTag } from "@/components/bui/RecordsTable";
import { ErrorNote } from "@/components/pikit/error-note";
import { every } from "@/lib/activity";
import { ApiFailure, useApi } from "@/lib/api";
import { formatAgo } from "@/lib/format";
import { Link, pagePath } from "@/lib/router";
import { defineView } from "@/lib/views";
import { BASE, ChecksLabel, StateLabel } from "./labels";
import { ProposalPage } from "./proposal";
import type { ProposalList, ProposalState, ProposalSummary } from "./types";

type Filter = "all" | ProposalState;

/** What the page shows before self-improvement is connected: what is missing, and the steps. */
function ConnectState({ missing }: { missing: string }) {
  const steps = [
    ["The repository", "Open Settings (the sidebar's foot) → Self-improvement, and set your project's GitHub repository, owner/name."],
    ["Two GitHub tokens, as secrets", "GITHUB_TOKEN for the agent, PIKIT_MERGE_TOKEN for your approvals: fine-grained, this repository only. Self-improvement lists their permissions and where to add them (on Cloudflare, the Worker's Variables and Secrets)."],
    ["A ruleset on GitHub", "Protect the default branch: a pull request required, the checks required, no force push."],
  ];
  return (
    <Page
      eyebrow="Proposals"
      title="Connect self-improvement"
      description="Your agent can propose changes to itself as GitHub pull requests, which you approve or reject here. It is off until it is connected to your project's repository."
    >
      <Section title="What is missing">
        <p className="text-[13px] text-ink-2 [overflow-wrap:anywhere]">{missing}</p>
      </Section>
      <Section title="How to connect it">
        <ol className="flex flex-col gap-3">
          {steps.map(([title, text], i) => (
            <li key={title} className="flex gap-3">
              <span className="flex size-6 shrink-0 items-center justify-center rounded-full bg-inset font-mono text-[12px] text-ink-2">{i + 1}</span>
              <div className="min-w-0 text-[13px] leading-relaxed text-ink-2">
                <div className="text-[14px] text-ink">{title}</div>
                {text}
              </div>
            </li>
          ))}
        </ol>
      </Section>
    </Page>
  );
}

function ProposalsPage() {
  const { data, error } = useApi<ProposalList>(BASE, every(60_000));
  const [filter, setFilter] = useState<Filter>("open");

  if (error instanceof ApiFailure && error.body.error === "not_connected") return <ConnectState missing={error.message} />;
  if (error !== undefined && data === undefined) {
    return (
      <Page eyebrow="Proposals">
        <ErrorNote error={error} title="The proposals cannot be read" />
      </Page>
    );
  }
  if (data === undefined) return <PageLoading eyebrow="Proposals" />;

  const count = (state: ProposalState) => data.proposals.filter((proposal) => proposal.state === state).length;
  const rows = filter === "all" ? data.proposals : data.proposals.filter((proposal) => proposal.state === filter);
  const open = count("open");
  const time = (at: string) => Date.parse(at);

  const columns: RecordColumn<ProposalSummary>[] = [
    {
      key: "title",
      label: "Proposal",
      icon: <GitPullRequest />,
      width: 340,
      title: (row) => row.title,
      cell: (row) => (
        <>
          <span className="mr-1.5 shrink-0 font-mono text-[12px] text-ink-3">#{row.number}</span>
          <Link to={pagePath(BASE, String(row.number))} className="records-name hover:underline">
            {row.title}
          </Link>
        </>
      ),
    },
    { key: "state", label: "State", icon: <Activity />, width: 120, sort: (a, b) => a.state.localeCompare(b.state), cell: (row) => <StateLabel state={row.state} draft={row.draft} /> },
    {
      key: "checks",
      label: "Checks",
      icon: <Activity />,
      width: 150,
      muted: (row) => row.checks === undefined,
      cell: (row) => (row.checks === undefined ? "—" : <ChecksLabel checks={row.checks} />),
    },
    { key: "branch", label: "Branch", icon: <GitBranch />, width: 200, title: (row) => row.branch, cell: (row) => <RecordTag mono>{row.branch.slice(data.branchPrefix.length) || row.branch}</RecordTag> },
    { key: "author", label: "By", icon: <User />, width: 130, cell: (row) => row.author },
    {
      key: "updated",
      label: "Updated",
      icon: <Clock />,
      width: 120,
      sort: (a, b) => time(a.updatedAt) - time(b.updatedAt),
      cell: (row) => <span className="text-ink-2">{formatAgo(time(row.closedAt ?? row.updatedAt))}</span>,
    },
  ];

  return (
    <Page
      eyebrow="Proposals"
      title={open === 0 ? "Nothing waiting for you" : `${open} ${open === 1 ? "change waits" : "changes wait"} for you`}
      description={
        <>
          The changes your agent proposes to itself: pull requests from <ValuePill>{data.branchPrefix}…</ValuePill> on{" "}
          <a className="underline decoration-line-strong underline-offset-2 hover:text-ink" href={`https://github.com/${data.repository}/pulls`} target="_blank" rel="noreferrer">
            {data.repository}
          </a>
          . Open one to read its description, its diff and its checks, then approve it (merged, then deployed) or reject it (closed).
        </>
      }
    >
      {error !== undefined && <ErrorNote error={error} title="Not read again" />}
      <Section
        title="Proposals"
        meta={data.proposals.length}
        tools={
          <FilterChips
            label="Show the proposals that are"
            value={filter}
            onChange={setFilter}
            filters={[
              { key: "open", label: "Open", tone: "blue", count: open },
              { key: "merged", label: "Merged", tone: "green", count: count("merged") },
              { key: "closed", label: "Rejected", tone: "neutral", count: count("closed") },
              { key: "all", label: "All", count: data.proposals.length },
            ]}
          />
        }
      >
        <RecordsTable
          label="The agent's proposals"
          columns={columns}
          rows={rows}
          rowKey={(row) => String(row.number)}
          empty={
            data.proposals.length === 0 ? (
              <EmptyState
                icon={<GitPullRequest />}
                title="No proposal yet"
                hint={`Ask your agent for a change to itself: it proposes it as a pull request from a branch ${data.branchPrefix}…, which shows here.`}
              />
            ) : (
              <EmptyState icon={<GitPullRequest />} title={`No proposal is ${filter === "closed" ? "rejected" : filter}`} hint="Pick another filter to see the others." />
            )
          }
        />
      </Section>
    </Page>
  );
}

export default defineView({
  id: "admin-proposals",
  title: "Proposals",
  icon: GitPullRequest,
  order: 40,
  pages: [
    { path: BASE, component: ProposalsPage, fill: true },
    { path: `${BASE}/:number`, component: ProposalPage, fill: true },
  ],
});

/** What the list and a proposal's page both show: a proposal's state and its checks, as pills. */

import { type PillTone, StatePill } from "@/components/bui/FilterTable";
import type { ProposalChecks, ProposalState } from "./types";

export const BASE = "/admin-proposals";

export const STATE_TONE: Record<ProposalState, PillTone> = { open: "blue", merged: "green", closed: "neutral" };
const STATE_LABEL: Record<ProposalState, string> = { open: "open", merged: "merged", closed: "rejected" };
export const CHECKS_TONE: Record<ProposalChecks["state"], PillTone> = { passing: "green", failing: "red", pending: "orange", none: "neutral" };

/** A state as the view says it: a closed proposal was rejected. */
export function StateLabel({ state, draft = false }: { state: ProposalState; draft?: boolean }) {
  return (
    <StatePill tone={STATE_TONE[state]}>
      {STATE_LABEL[state]}
      {draft && state === "open" && " · draft"}
    </StatePill>
  );
}

/** The checks in a word and a count: `passing 3/3`, `failing 1`. */
export function ChecksLabel({ checks }: { checks: ProposalChecks }) {
  const total = checks.passed + checks.failed + checks.pending;
  const figure = checks.state === "failing" ? `${checks.failed} of ${total}` : checks.state === "pending" ? `${checks.pending} of ${total}` : checks.state === "passing" ? `${checks.passed}` : "";
  return (
    <StatePill tone={CHECKS_TONE[checks.state]} title={checks.items.map((item) => `${item.name}: ${item.detail}`).join("\n") || "No check ran on this change"}>
      {checks.state === "none" ? "no checks" : checks.state}
      {figure !== "" && ` · ${figure}`}
    </StatePill>
  );
}

/**
 * One proposal: the agent's description (markdown), its checks, its diff file by file, and Approve /
 * Reject, each behind a confirmation. Approve sends the head commit the page shows, so a branch the
 * agent pushed again since is not merged unread; when the checks do not pass, the confirmation says
 * so and approves anyway (`override`).
 */

import { Activity, GitPullRequest, InfoCircle, OpenNewWindow } from "iconoir-react";
import { useState } from "react";
import { Button } from "@/components/bui/Button";
import { ValuePill } from "@/components/bui/Chip";
import EmptyState from "@/components/bui/EmptyState";
import { Page, PageLoading, Section } from "@/components/bui/Page";
import RecordsTable, { type RecordColumn, RecordName, RecordTag } from "@/components/bui/RecordsTable";
import { ErrorNote } from "@/components/pikit/error-note";
import { Markdown } from "@/components/pikit/markdown";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { every } from "@/lib/activity";
import { post, useApi } from "@/lib/api";
import { formatAgo } from "@/lib/format";
import { Link } from "@/lib/router";
import { BASE, ChecksLabel, StateLabel } from "./labels";
import type { ApproveRequest, ProposalCheck, ProposalDetail, ProposalFile, RejectRequest } from "./types";

const CHECK_TONE = { passing: "green", failing: "red", pending: "orange", skipped: "neutral" } as const;
/** A file this long (lines changed) starts folded. */
const FOLDED = 400;

const linkClass = "inline-flex items-center gap-1 underline decoration-line-strong underline-offset-2 hover:text-ink";

/** A line of a unified diff, coloured by what it is. */
function lineClass(line: string): string {
  if (line.startsWith("@@")) return "bg-inset text-ink-3";
  if (line.startsWith("+")) return "bg-green-tint text-ink";
  if (line.startsWith("-")) return "bg-red-tint text-ink";
  return "text-ink-2";
}

function FileDiff({ file }: { file: ProposalFile }) {
  const lines = file.patch?.split("\n") ?? [];
  return (
    <details open={file.additions + file.deletions <= FOLDED} className="group overflow-hidden rounded-card bg-surface shadow-card">
      <summary className="flex h-11 cursor-pointer items-center gap-2 px-4 text-[12.5px] group-open:border-b group-open:border-line">
        <span className="min-w-0 truncate font-mono text-ink" title={file.path}>
          {file.previousPath !== undefined ? `${file.previousPath} → ${file.path}` : file.path}
        </span>
        <RecordTag>{file.status}</RecordTag>
        <span className="ml-auto shrink-0 font-mono text-[12px] text-green">+{file.additions}</span>
        <span className="shrink-0 font-mono text-[12px] text-red">-{file.deletions}</span>
      </summary>
      {file.patch === undefined ? (
        <p className="px-4 py-3 text-[12.5px] text-ink-3">
          {file.truncated ? "Not shown: the diff is too large for this page. Read it on GitHub." : "No diff to show: a binary file, or one GitHub does not diff."}
        </p>
      ) : (
        <div className="overflow-x-auto py-2 font-mono text-[12px] leading-[1.6]">
          {lines.map((line, i) => (
            <div key={i} className={`min-w-max px-4 whitespace-pre ${lineClass(line)}`}>
              {line === "" ? " " : line}
            </div>
          ))}
          {file.truncated && <div className="px-4 pt-2 font-sans text-[12.5px] text-ink-3">Cut here: the rest is on GitHub.</div>}
        </div>
      )}
    </details>
  );
}

const checkColumns: RecordColumn<ProposalCheck>[] = [
  {
    key: "name",
    label: "Check",
    icon: <Activity />,
    width: 320,
    title: (check) => check.name,
    cell: (check) =>
      check.url === undefined ? (
        <RecordName>{check.name}</RecordName>
      ) : (
        <a className="records-name hover:underline" href={check.url} target="_blank" rel="noreferrer">
          {check.name}
        </a>
      ),
  },
  {
    key: "state",
    label: "State",
    icon: <Activity />,
    width: 130,
    cell: (check) => <ValuePill tone={CHECK_TONE[check.state]}>{check.state}</ValuePill>,
  },
  { key: "detail", label: "Detail", icon: <InfoCircle />, width: 300, title: (check) => check.detail, cell: (check) => check.detail },
];

type Dialog = "approve" | "reject" | undefined;

export function ProposalPage({ params }: { params: Record<string, string> }) {
  // Its own state per proposal: another proposal's page starts afresh.
  return <Proposal key={params.number} number={params.number ?? ""} />;
}

function Proposal({ number }: { number: string }) {
  const path = `${BASE}/${encodeURIComponent(number)}`;
  const { data, error, reload } = useApi<ProposalDetail>(path, every(60_000));
  const [dialog, setDialog] = useState<Dialog>();
  const [comment, setComment] = useState("");
  const [busy, setBusy] = useState(false);
  const [actionError, setActionError] = useState<Error>();
  const [done, setDone] = useState<string>();

  if (error !== undefined && data === undefined) {
    return (
      <Page eyebrow={`Proposal #${number}`}>
        <ErrorNote error={error} title="This proposal cannot be read" />
        <Link to={BASE} className="text-[13px] text-ink-2 underline underline-offset-2">
          Back to the proposals
        </Link>
      </Page>
    );
  }
  if (data === undefined) return <PageLoading eyebrow={`Proposal #${number}`} />;

  const passing = data.checks.state === "passing";
  const act = async (action: "approve" | "reject") => {
    setBusy(true);
    setActionError(undefined);
    try {
      if (action === "approve") {
        const body: ApproveRequest = { sha: data.headSha, ...(!passing && { override: true }) };
        await post(`${path}/approve`, body);
        setDone("Approved: merged into the default branch. The deploy follows.");
      } else {
        const body: RejectRequest = comment.trim() === "" ? {} : { comment: comment.trim() };
        await post(`${path}/reject`, body);
        setDone("Rejected: the pull request is closed.");
        setComment("");
      }
      reload();
    } catch (thrown) {
      setActionError(thrown instanceof Error ? thrown : new Error(String(thrown)));
      reload();
    } finally {
      setBusy(false);
    }
  };

  const checksWord = data.checks.state === "failing" ? `${data.checks.failed} failing` : data.checks.state === "pending" ? `${data.checks.pending} still running` : "none ran";
  const wrongBase = data.base !== data.defaultBranch;

  return (
    <Page
      eyebrow={`Proposal #${data.number}`}
      title={data.title}
      aside={
        <>
          <StateLabel state={data.state} draft={data.draft} />
          {data.state === "open" && (
            <>
              <Button size="sm" variant="secondary" disabled={busy} onClick={() => setDialog("reject")}>
                Reject
              </Button>
              <Button size="sm" variant="primary" disabled={busy || wrongBase} onClick={() => setDialog("approve")}>
                Approve
              </Button>
            </>
          )}
        </>
      }
      description={
        <>
          <span className="text-ink">{data.author}</span> proposes <ValuePill>{data.branch}</ValuePill> into <ValuePill>{data.base}</ValuePill>, updated{" "}
          {formatAgo(Date.parse(data.updatedAt))}: <span className="font-mono text-green">+{data.additions}</span> <span className="font-mono text-red">-{data.deletions}</span> in{" "}
          {data.changedFiles} {data.changedFiles === 1 ? "file" : "files"}.{" "}
          <a className={linkClass} href={data.url} target="_blank" rel="noreferrer">
            On GitHub <OpenNewWindow width={12} height={12} />
          </a>
          {data.previewUrl !== undefined && (
            <>
              {" · "}
              <a className={linkClass} href={data.previewUrl} target="_blank" rel="noreferrer">
                Preview <OpenNewWindow width={12} height={12} />
              </a>
            </>
          )}
          {" · "}
          <Link to={BASE} className={linkClass}>
            All proposals
          </Link>
        </>
      }
    >
      {done !== undefined && <p className="rounded-card bg-green-tint px-3 py-2.5 text-[13px] text-green">{done}</p>}
      {actionError !== undefined && <ErrorNote error={actionError} title="Not done" />}
      {error !== undefined && <ErrorNote error={error} title="Not read again" />}
      {wrongBase && (
        <p className="rounded-card bg-orange-tint px-3 py-2.5 text-[13px] text-orange">
          It merges into {data.base}, not {data.defaultBranch}, the default branch: it cannot be approved here.
        </p>
      )}
      {data.state === "open" && data.mergeable === false && (
        <p className="rounded-card bg-orange-tint px-3 py-2.5 text-[13px] text-orange">GitHub cannot merge it as it is ({data.mergeableState}): ask the agent to bring it up to date.</p>
      )}

      <Section title="Description" meta="the agent's">
        <div className="rounded-card bg-surface px-5 py-4 text-[14px] leading-relaxed shadow-card">
          {data.body.trim() === "" ? <span className="text-ink-3">No description.</span> : <Markdown text={data.body} />}
        </div>
      </Section>

      <Section title="Checks" meta={<ChecksLabel checks={data.checks} />}>
        <RecordsTable
          label="The checks of the proposal's head commit"
          columns={checkColumns}
          rows={data.checks.items}
          rowKey={(check) => `${check.name}#${check.url ?? ""}#${check.detail}`}
          empty={<EmptyState icon={<Activity />} title="No check ran" hint="The project's workflow (.github/workflows/pikit-checks.yml) runs on every pull request." />}
        />
      </Section>

      <Section title="Changes" meta={data.files.length < data.changedFiles ? `the first ${data.files.length} of ${data.changedFiles} files` : `${data.changedFiles} ${data.changedFiles === 1 ? "file" : "files"}`}>
        {data.files.length === 0 ? (
          <div className="rounded-card bg-surface shadow-card">
            <EmptyState icon={<GitPullRequest />} title="No file changed" />
          </div>
        ) : (
          <div className="flex flex-col gap-3">
            {data.files.map((file) => (
              <FileDiff key={file.path} file={file} />
            ))}
          </div>
        )}
      </Section>

      <AlertDialog open={dialog === "approve"} onOpenChange={(open) => !open && setDialog(undefined)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{passing ? `Approve #${data.number}?` : `Approve #${data.number} anyway?`}</AlertDialogTitle>
            <AlertDialogDescription>
              {passing
                ? `It is squash-merged into ${data.base}, and the deploy follows.`
                : `Its checks did not pass (${checksWord}). Merged into ${data.base} as it is, it deploys untested: approve it only if you read the change.`}
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction className={passing ? undefined : "bg-red text-white hover:bg-red/90"} onClick={() => void act("approve")}>
              {passing ? "Approve and merge" : "Approve anyway"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      <AlertDialog open={dialog === "reject"} onOpenChange={(open) => !open && setDialog(undefined)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Reject #{data.number}?</AlertDialogTitle>
            <AlertDialogDescription>The pull request is closed, unmerged. A comment, if you write one, is left on it for the agent to read.</AlertDialogDescription>
          </AlertDialogHeader>
          <textarea
            value={comment}
            onChange={(event) => setComment(event.target.value)}
            maxLength={10_000}
            rows={3}
            placeholder="Why (optional)"
            aria-label="A comment for the agent (optional)"
            className="w-full resize-y rounded-lg bg-field px-3 py-2 text-[13px] text-ink shadow-[var(--shadow-hairline)] outline-none placeholder:text-ink-3"
          />
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction className="bg-red text-white hover:bg-red/90" onClick={() => void act("reject")}>
              Reject
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </Page>
  );
}

/**
 * What admin-proposals' routes answer (`/admin/api/admin-proposals/*`), as JSON. The view
 * (`src/dashboard/src/views/admin-proposals/types.ts`) keeps an identical copy: change both together.
 *
 * A proposal is a pull request of the project's repository whose head branch starts with the prefix
 * (`pikit/self/`) and lives in that same repository (never a fork's).
 */

/** Where a proposal is: still open, merged (approved), or closed without merging (rejected). */
export type ProposalState = "open" | "merged" | "closed";

/** One check of the proposal's head commit: a check run (GitHub Actions, Workers Builds) or a commit status. */
export interface ProposalCheck {
  name: string;
  state: "passing" | "failing" | "pending" | "skipped";
  /** GitHub's conclusion or status (`failure`, `in_progress`, `success`…). */
  detail: string;
  url?: string;
}

/**
 * Every check of the head commit, summed up: `failing` when one fails, else `pending` while one runs,
 * else `passing` when at least one passed, else `none` (no check ran: the project's workflow is missing).
 */
export interface ProposalChecks {
  state: "passing" | "failing" | "pending" | "none";
  passed: number;
  failed: number;
  pending: number;
  items: ProposalCheck[];
}

export interface ProposalSummary {
  number: number;
  title: string;
  /** Who opened the pull request (the agent's token's account). */
  author: string;
  /** The head branch, under the prefix. */
  branch: string;
  /** ISO 8601, as GitHub gives them. */
  createdAt: string;
  updatedAt: string;
  closedAt?: string;
  state: ProposalState;
  draft: boolean;
  /** The head commit's checks; read for open proposals only. */
  checks?: ProposalChecks;
  /** The pull request on GitHub. */
  url: string;
  /** A preview of the change when one is found (a Workers Builds preview's `*.workers.dev` URL). */
  previewUrl?: string;
}

/** `GET /admin/api/admin-proposals`: the open proposals, then the recently closed ones, newest first. */
export interface ProposalList {
  repository: string;
  branchPrefix: string;
  proposals: ProposalSummary[];
}

/** One changed file; `patch` is cut at `MAX_PATCH` characters, and left out once the whole diff is past `MAX_DIFF`. */
export interface ProposalFile {
  path: string;
  /** `added`, `removed`, `modified`, `renamed`… (GitHub's). */
  status: string;
  previousPath?: string;
  additions: number;
  deletions: number;
  /** The unified diff's hunks; absent for a binary file, a file GitHub does not diff, or past the bound. */
  patch?: string;
  /** Whether `patch` was cut or left out by the bound. */
  truncated: boolean;
}

/** `GET /admin/api/admin-proposals/:number`. */
export interface ProposalDetail extends ProposalSummary {
  /** The agent's description of the change (markdown). */
  body: string;
  /** The branch it merges into, and the repository's default branch: Approve needs them equal. */
  base: string;
  defaultBranch: string;
  /** The head commit: Approve sends it back, so a branch moved since it was read is not merged. */
  headSha: string;
  /** GitHub's: `null` while it is computing it. */
  mergeable: boolean | null;
  /** GitHub's `mergeable_state` (`clean`, `dirty`, `blocked`, `unstable`, `unknown`…). */
  mergeableState: string;
  additions: number;
  deletions: number;
  changedFiles: number;
  /** The first `MAX_FILES` files. */
  files: ProposalFile[];
  checks: ProposalChecks;
}

/** `POST /admin/api/admin-proposals/:number/approve`'s body. */
export interface ApproveRequest {
  /** The head commit the operator reviewed: refused (`409 changed`) when the branch moved since. */
  sha?: string;
  /** Merge although the checks fail, are pending or never ran. */
  override?: boolean;
}

/** `POST /admin/api/admin-proposals/:number/reject`'s body. */
export interface RejectRequest {
  /** Left on the pull request before it is closed (markdown, at most `MAX_COMMENT` characters). */
  comment?: string;
}

export interface ApproveResponse {
  number: number;
  merged: true;
  /** The squashed commit on the default branch. */
  sha: string;
}

export interface RejectResponse {
  number: number;
  closed: true;
}

/** One part of the connection, as `GET /admin/api/admin-proposals/status` checks it. */
export interface ConnectionCheck {
  /** `ok`; `missing` (not set yet); `failing` (set, and wrong); `unknown` (not checked, or GitHub did not say). */
  state: "ok" | "missing" | "failing" | "unknown";
  /** What was found, or what to do: names a secret, never holds one. */
  message: string;
}

/**
 * `GET /admin/api/admin-proposals/status`: whether self-improvement is connected, checked live. It is
 * when the repository is set and the read token reads it, and the merge token is set and another
 * token. The ruleset is best effort: GitHub's rules for the default branch, read with the read token.
 */
export interface ConnectionStatus {
  connected: boolean;
  /** `owner/name`, the setting's (or the config's); empty when none. */
  repository: string;
  branchPrefix: string;
  /** The secrets' names: `GITHUB_TOKEN`, `PIKIT_MERGE_TOKEN` unless the config says otherwise. */
  tokenSecret: string;
  mergeTokenSecret: string;
  /** The repository's default branch, when it was read. */
  defaultBranch?: string;
  checks: {
    /** The repository is set, and GitHub has it. */
    repository: ConnectionCheck;
    /** The read token is set, and reads the repository. */
    readToken: ConnectionCheck;
    /** The merge token is set, and is not the read token (it is never sent to check it). */
    mergeToken: ConnectionCheck;
    /** A ruleset requires a pull request on the default branch. */
    ruleset: ConnectionCheck;
  };
}

/**
 * An error: `unauthorized` 401; `invalid_request` 400; `not_found` 404 (no such pull request);
 * `not_a_proposal` 404 to a read, 409 to an action (its head is not a branch under the prefix of the
 * repository); `not_open`, `wrong_base`, `checks_failing`, `changed`, `not_mergeable` 409;
 * `too_large` 413; `rate_limited` 429 (with `retry-after`); `not_connected` 503 (no repository, or a
 * token missing: self-improvement is not connected yet, and the message says what to set);
 * `not_configured` 503 (the same token in both secrets); `github_unauthorized`, `github_forbidden`,
 * `github_not_found`, `github_unavailable`, `github_refused` 502. Never a token.
 */
export interface ProposalError {
  error: string;
  message?: string;
}

/** The most files a proposal's page lists (GitHub's page). */
export const MAX_FILES = 100;
/** One file's patch is cut past this many characters. */
export const MAX_PATCH = 60_000;
/** Once the patches sent add up to this many characters, the next ones are left out. */
export const MAX_DIFF = 400_000;
/** The longest comment a rejection leaves. */
export const MAX_COMMENT = 10_000;
